// The hidden Ente password: 32 random bytes, generated by the first device to
// sign in and kept in one file on the app's zero-knowledge drive, so every
// device that signs in with Homebase finds the same one. It isn't derived
// from any Homebase secret, which can change on a new consent.

import { randomBytes, toBase64Url, utf8 } from "./bytes";
import { passwordFile } from "./constants";
import { sha256 } from "./crypto";
import { type HomebaseDrive, isExistingUniqueIdError } from "./drive";

export interface EntePassword {
    password: string;
    /** Whether this sign-in made it (the first for this identity). */
    created: boolean;
}

const readPassword = async (drive: HomebaseDrive) => {
    const header = await drive.getHeaderByUniqueId(passwordFile.uniqueId);
    if (!header) return undefined;
    const password = await drive.decryptContent(header);
    if (!password) throw new Error("The password file on Homebase is empty");
    return password;
};

/**
 * The Ente password on the drive, creating it if this is the first sign-in.
 * An existing password file is never overwritten: if another device creates
 * one first, this reads that one.
 */
export const ensureEntePassword = async (
    drive: HomebaseDrive,
): Promise<EntePassword> => {
    const existing = await readPassword(drive);
    if (existing) return { password: existing, created: false };

    const password = toBase64Url(randomBytes(32));
    try {
        await drive.createFile({
            uniqueId: passwordFile.uniqueId,
            fileType: passwordFile.fileType,
            content: password,
        });
        return { password, created: true };
    } catch (e) {
        if (!isExistingUniqueIdError(e)) throw e;
        const winner = await readPassword(drive);
        if (!winner) throw e;
        return { password: winner, created: false };
    }
};

/** First 8 hex digits of the password's SHA-256: safe to show. */
export const passwordFingerprint = async (password: string) =>
    Array.from((await sha256(utf8(password))).slice(0, 4), (b) =>
        b.toString(16).padStart(2, "0"),
    ).join("");
